#[tokio::test(flavor = "multi_thread")]
async fn test_token_endpoint_error_response_parsed_to_typed_error() {
    // RFC 6749 §5.2: a 4xx response with a JSON error object must surface as a
    // typed OAuth2ServerError carrying code/description/uri.
    let client = Arc::new(FakeApiClient::new());
    client.enqueue(
        r#"{"error":"invalid_grant","error_description":"refresh token expired","error_uri":"https://docs.example.com/errors/invalid_grant"}"#,
        400,
    );

    let manager = OAuth2TokenManager::new();
    manager.set_api_client(client);

    let mut params = HashMap::new();
    params.insert("grant_type".to_string(), "client_credentials".to_string());

    let err = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .expect_err("4xx error response must error");
    let server_err = err
        .downcast_ref::<OAuth2ServerError>()
        .expect("expected OAuth2ServerError");
    assert_eq!(400, server_err.status_code());
    assert_eq!(Some("invalid_grant"), server_err.code());
    assert_eq!(Some("refresh token expired"), server_err.description());
    assert_eq!(
        Some("https://docs.example.com/errors/invalid_grant"),
        server_err.uri()
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn test_invalidate_triggers_single_refetch_under_concurrency() {
    // After invalidation, 10 concurrent callers must coalesce into exactly ONE
    // additional token request (single-flight), all observing the refreshed
    // token. The manager holds its inner mutex across the network call so only
    // the first waiter performs the round-trip.
    let client = Arc::new(CountingApiClient::new(
        r#"{"access_token":"tok-refetched","expires_in":3600}"#,
        50,
    ));

    let manager = Arc::new(OAuth2TokenManager::new());
    manager.set_api_client(client.clone());

    let mut params = HashMap::new();
    params.insert("grant_type".to_string(), "client_credentials".to_string());

    let first = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .expect("first call should succeed");
    assert_eq!("tok-refetched", first);
    assert_eq!(1, client.calls());

    manager.invalidate_access_token().await;

    let mut handles = Vec::new();
    for _ in 0..10 {
        let manager = manager.clone();
        handles.push(tokio::spawn(async move {
            let mut params = HashMap::new();
            params.insert("grant_type".to_string(), "client_credentials".to_string());
            manager
                .get_access_token("https://auth.example.com/token", &params)
                .await
                .expect("refetch should succeed")
        }));
    }
    for handle in handles {
        let token = handle.await.expect("task should not panic");
        assert_eq!("tok-refetched", token);
    }

    assert_eq!(
        2,
        client.calls(),
        "invalidate + concurrent callers must collapse onto a single refetch"
    );
}

/// `Send` and `Sync` follow from the fields, so the type needs no `unsafe impl`
/// that would assert them regardless of what the fields hold.
#[test]
fn test_oauth2_token_manager_is_send_and_sync_without_unsafe_impls() {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<OAuth2TokenManager>();

    let source = include_str!("../src/auth/oauth/oauth2_token_manager.rs");
    assert!(
        !source.contains("unsafe impl"),
        "oauth2_token_manager.rs must not carry an unsafe impl"
    );
}

fn authorization_code_params() -> HashMap<String, String> {
    let mut params = HashMap::new();
    params.insert("grant_type".to_string(), "authorization_code".to_string());
    params.insert("code".to_string(), "abc".to_string());
    params.insert("client_id".to_string(), "cid".to_string());
    params.insert("client_secret".to_string(), "sec".to_string());
    params
}

/// A stale token is renewed with the refresh grant: the cached refresh token
/// plus the client credentials, and nothing of the original grant.
#[tokio::test(flavor = "multi_thread")]
async fn test_refresh_request_carries_the_refresh_token_and_the_client_credentials() {
    let client = Arc::new(FakeApiClient::new());
    client.enqueue(
        r#"{"access_token":"old","refresh_token":"ref1","expires_in":1}"#,
        200,
    );
    client.enqueue(r#"{"access_token":"new","expires_in":3600}"#, 200);
    let manager = OAuth2TokenManager::new();
    manager.set_api_client(client.clone());
    let params = authorization_code_params();

    let first = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();
    let second = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();

    assert_eq!(("old", "new"), (first.as_str(), second.as_str()));
    let requests = client.requests();
    assert_eq!(2, requests.len());
    assert_eq!(
        pairs_of(&[
            ("client_id", "cid"),
            ("client_secret", "sec"),
            ("code", "abc"),
            ("grant_type", "authorization_code"),
        ]),
        form_pairs(&requests[0].1)
    );
    assert_eq!(
        pairs_of(&[
            ("client_id", "cid"),
            ("client_secret", "sec"),
            ("grant_type", "refresh_token"),
            ("refresh_token", "ref1"),
        ]),
        form_pairs(&requests[1].1)
    );
}

/// When the refresh grant is rejected the manager falls back to the original
/// grant instead of surfacing the refresh failure, and keeps the new refresh
/// token that grant returns.
#[tokio::test(flavor = "multi_thread")]
async fn test_failed_refresh_falls_back_to_the_original_grant() {
    let client = Arc::new(FakeApiClient::new());
    client.enqueue(
        r#"{"access_token":"old","refresh_token":"ref1","expires_in":1}"#,
        200,
    );
    client.enqueue(r#"{"error":"invalid_grant"}"#, 400);
    client.enqueue(
        r#"{"access_token":"fresh","refresh_token":"ref2","expires_in":3600}"#,
        200,
    );
    let manager = OAuth2TokenManager::new();
    manager.set_api_client(client.clone());
    let params = authorization_code_params();

    manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();
    let token = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .expect("a rejected refresh must fall back to the original grant");

    assert_eq!("fresh", token);
    assert_eq!("ref2", manager.refresh_token().await);
    let requests = client.requests();
    assert_eq!(3, requests.len());
    assert!(
        form_pairs(&requests[1].1)
            .contains(&("grant_type".to_string(), "refresh_token".to_string())),
        "the second request must be the refresh grant: {}",
        requests[1].1
    );
    assert_eq!(form_pairs(&requests[0].1), form_pairs(&requests[2].1));
}

/// A refresh that fails at the transport level also falls back to the
/// original grant.
#[tokio::test(flavor = "multi_thread")]
async fn test_refresh_transport_failure_falls_back_to_the_original_grant() {
    let client = Arc::new(FakeApiClient::new());
    client.enqueue(
        r#"{"access_token":"old","refresh_token":"ref1","expires_in":1}"#,
        200,
    );
    client.enqueue_error(Box::new(NetworkError::from(ApiError::new(
        0,
        "connection reset".to_string(),
        None,
        None,
    ))));
    client.enqueue(r#"{"access_token":"fresh","expires_in":3600}"#, 200);
    let manager = OAuth2TokenManager::new();
    manager.set_api_client(client.clone());
    let params = authorization_code_params();

    manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();
    let token = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .expect("a refresh that cannot reach the endpoint must fall back");

    assert_eq!("fresh", token);
    assert_eq!(3, client.requests().len());
}

