/// A refresh response without `expires_in` keeps the expiry the token already
/// had, so a token that was stale stays stale and the next call renews it again.
#[tokio::test(flavor = "multi_thread")]
async fn test_refresh_without_expires_in_keeps_the_existing_expiry() {
    let client = Arc::new(FakeApiClient::new());
    client.enqueue(
        r#"{"access_token":"t1","refresh_token":"ref1","expires_in":1}"#,
        200,
    );
    client.enqueue(r#"{"access_token":"t2"}"#, 200);
    client.enqueue(r#"{"access_token":"t3"}"#, 200);
    let manager = OAuth2TokenManager::new();
    manager.set_api_client(client.clone());
    let params = authorization_code_params();

    manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();
    let second = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();
    let third = manager
        .get_access_token("https://auth.example.com/token", &params)
        .await
        .unwrap();

    assert_eq!(("t2", "t3"), (second.as_str(), third.as_str()));
    assert_eq!(3, client.requests().len());
}

